content.css:
#top-nav-bar {
    display: flex;
    position: absolute;
    top: 0;
    height: 30px;
    padding: 0px 10px;
    right: 0;
}

#top-nav-bar .nav-items {
    display: flex;
    height: 100%;
    flex-direction: row-reverse;
    align-items: center;
    text-align: center;
    font-size: 16px;
    color: #333;
}

.nav-items.right {
    justify-content: end;
    text-align: right;
}

.nav-items.left {
    justify-content: start;
    text-align: left;
}

.nav-items.right > div {
    width: 30px;
    height: 30px;
}

.vbi-info-icon {
    order: 2;
    width: 28px;
    height: 22px !important;
    margin-left: 2px;
    margin-top: -2px;
}

.vbi-display-data-icon {
    order: 3;
}

.nav-items.right .icon {
    font-size: 24px;
}

.vbi-display-data-icon .icon:hover {
    color: #0078d4;
}

.vbi-display-data-icon img {
    width: 28px;
    height: 26px;
    margin-top: 2px;
    margin-right: 2px;
}

.vbi-license-alert-icon {
    order: 1;
    width: 21px !important;
    height: 21px !important;
    margin-top: 2px;
    margin-right: 2px;
}

#vbi-annotation-icon {
    order: 5;
    height: auto;
    width: auto;
}
div#vbi-annotation-icon span {
    font-size: 18px;
    line-height: 32px;
    width: 30px;
    height: 30px;
    color: #666666;
}
div#vbi-annotation-icon span.active {
    color: #0078d4;
}

.isEditMode #vbi-edit-icon {
    top: 75px !important;
}

.isEditMode #top-nav-bar {
    top: 40px;
}

/*Settings Icon is Only IBCS Components*/
#pbi-icon-container .settings_icon {
    order: 4;
    padding-left: 14px;
}

.editor-icon {
    order: 7;
    width: 27px !important;
    height: 27px !important;
    border-radius: 50%;
    background-color: #f2c811;
    opacity: 0.8;
    text-align: center;
    line-height: 28px;
    margin-right: 8px;
}
.editor-icon .icon {
    font-size: 12px !important;
    color: #000;
}

.editor-icon:hover {
    -webkit-box-shadow: -5px 4px 20px 2px rgba(20, 20, 20, 0.2);
    -moz-box-shadow: -5px 4px 20px 2px rgba(20, 20, 20, 0.2);
    box-shadow: -5px 4px 20px 2px rgba(20, 20, 20, 0.2);
    opacity: 1;
}

.editor-icon img {
    border-style: none;
    width: 13px;
    position: relative;
    top: 1px;
    left: 1px;
}

.colorScale-rtl-disable > span {
    left: 0px !important;
}

.colorScale-rtl{
    left: 128px !important;
}

.colorScale-rtl-lowFontSize {
    margin-left: 21px !important;
}

.colorScale-rtl-highFontSize {
    margin-left: 34px !important;
}

.highcharts-legend-item.colorScale-legend .highcharts-point {
    display: none;
}


