/* Grid Component */
/** Loading Gradient **/
@-webkit-keyframes LoadingGradient {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}
@-moz-keyframes LoadingGradient {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}
@keyframes LoadingGradient {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}
.grid-container-div * {
  box-sizing: border-box;
}
.gridatron.grid-container {
  position: relative;
}
.gridatron.grid-container:focus,
.gridatron.grid-container:active {
  outline: 0;
}
.gridatron .grid-loading-overlay {
  visibility: collapse;
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 11;
  background-color: rgba(0, 0, 0, 0.5);
  transition: 0.5s all;
  opacity: 0;
}
.gridatron .grid-loading-overlay.visible {
  visibility: visible;
  opacity: 1;
}
.gridatron .grid-loader {
  height: 3px;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  background: linear-gradient(-45deg, #3F51B5, #56a9e8);
  background-size: 400% 400%;
  -webkit-animation: LoadingGradient 2s ease infinite;
  -moz-animation: LoadingGradient 2s ease infinite;
  animation: LoadingGradient 2s ease infinite;
}
.grid-fixed-container {
  overflow: hidden !important;
  z-index: 9;
  background-color: #FFF;
  /* box-shadow: 2px -1px 4px #EEE; */
}
