  align-items: center;
}
.gridatron .grid-cell .cell-view {
  display: flex;
  align-items: center;
  height: 32px;
  font-family: inherit;
  flex-grow: 1;
  min-width: 0;
}
.gridatron .grid-td .grid-cell .cell-value {
  min-width: 0;
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;
}
.gridatron .grid-cell input {
  height: 24px;
