}
/** Styles for showing hierarchical columns */
.gridatron .grid-td.hier .grid-cell .icon.hier {
  height: 12px;
  width: 12px;
  background-size: 12px 12px;
  content: "";
  position: absolute;
  margin-left: -24px;
  top: 50%;
  margin-top: -6px;
  z-index: 1;
  background-size: 100%;
  border: 1px #DDD solid;
  display: flex;
  align-items: center;
  justify-content: center;
}
.gridatron .grid-td.hier .grid-cell .icon.hier {
  opacity: 1;
}
.gridatron .grid-td.hier.collapsed .grid-cell .icon.hier.collapsed:before {
  content: "\f102";
}
.gridatron .grid-td.hier.uncollapsed .grid-cell .icon.hier.uncollapsed,
.gridatron .grid-td.hier.collapsed .grid-cell .icon.hier.collapsed {
  font-family: "EditorIcons";
}
.gridatron .grid-td.hier.uncollapsed .grid-cell .icon.hier.uncollapsed:before {
  content: "\f103";
}
.gridatron .grid-td.hier.has-child .grid-cell .icon.hier.has-child {
