  text-overflow: ellipsis;
  white-space: nowrap;
}
/** Grid Cell Styles for selected **/
.gridatron .grid-td.selected {
  background-color: #e3f2fd66;
}
.gridatron .grid-td.selected:not(.active):not(.selected-row):not(.selected-col) .grid-cell {
