  box-shadow: none;
}
.gridatron .grid-td.last-col.selected.selected-row .grid-cell {
  border-right: 2px #56a9e8 solid;
}
.gridatron .grid-td.selected.selected-col .grid-cell {
  border-left: 2px #56a9e8 solid;
  border-right: 2px #56a9e8 solid;
}
.gridatron .grid-td.selected.selected-left .grid-cell {
  border-left: 0 !important;
}
.gridatron .grid-td.selected.selected-right .grid-cell {
  border-right: 0 !important;
}
.gridatron .grid-td.first-row.selected.selected-col .grid-cell {
  border-top: 2px #56a9e8 solid;
}
.gridatron .grid-td.first-col.selected.selected-row .grid-cell {
  box-shadow: none;
}
.gridatron .grid-td.last-row.selected.selected-col .grid-cell {
  border-bottom: 2px #56a9e8 solid;
}
/** Grid Cell Styles for highlight **/
.gridatron .grid-td.highlight {
  background-color: #fffae9;
}
.gridatron .grid-td.active.highlight .grid-cell {
  box-shadow: inset 0 0 0px 2px #56a9e8;
}
/** note trigger icon */
.gridatron .grid-td .note-icon {
  position: absolute;
  top: -1px;
  right: -4.5px;
  border-color: transparent transparent #FF9800 transparent;
  border-style: solid;
  border-width: 0px 7px 7px 7px;
  height: 0px;
  width: 0px;
  -webkit-transform: rotate(45deg);
}
.gridatron .grid-td.highlight .note-icon {
  border-color: transparent transparent #FFC107 transparent;
  border-width: 0px 8px 8px 8px;
}
.gridatron .grid-td.active .note-icon {
  border-color: transparent transparent #56a9e8 transparent;
  border-width: 0px 8px 8px 8px;
}
/* edited icon */
.gridatron .grid-td .edit-icon {
  color: #2e8ab8;
}
.gridatron .grid-td .edit-icon::before {
  content: "\E038 ";
  font-family: 'SAP-icons';
  position: absolute;
  top: 1px;
  left: 2px;
}
.gridatron .grid-td.active .active-cell-clear {
  position: absolute;
  height: 20px;
  background-color: #56a9e8;
  bottom: -18px;
  right: -1px;
  left: 0;
  border-radius: 0 0 2px 2px;
  transition: all 0.2s;
  text-align: left;
  font-size: 10px;
  color: #fff;
  line-height: 20px;
  padding-left: 16px;
  z-index: 999;
}
.gridatron .grid-td.active .active-cell-clear::before {
  font-family: 'EditorIcons';
  content: "\F123";
  position: absolute;
  left: 4px;
  font-size: 8px;
}
.gridatron .grid-td.active .active-cell-clear:hover {
  background-color: #1876d2;
}
/** Grid Cell Styles for locked **/
.gridatron .grid-th.locked .grid-cell {
  background-color: #DDD;
}
.gridatron .grid-th.locked::before {
  color: #AAA;
  font-size: 10px;
  font-family: 'EditorIcons';
  content: "\f118";
  position: absolute;
  top: 4px;
  left: 4px;
}
.gridatron .grid-th.locked.selected .grid-cell {
  background-color: #a1d6ff;
}
.gridatron .grid-th.selected.locked::before {
  color: #000;
}
.gridatron .grid-td.locked .grid-cell {
  background-color: #F7F7F7;
  border-right: 1px solid #DDD;
}
.gridatron .grid-td.locked::before {
  color: #CCC;
  font-size: 10px;
  font-family: 'EditorIcons';
  content: "\f118";
  position: absolute;
  top: 4px;
  left: 4px;
}
.gridatron .grid-td.active.locked::before {
  color: #56a9e8;
}
/* readyOnly */
.gridatron .grid-td.active.readOnly .grid-cell {
  box-shadow: inset 0 0 0 2px #c8c8c8;
}
.gridatron .grid-td.readOnly .grid-cell,
