/**
  Annotations
*/
p em {
  background: unset !important;
}
.annotate-box {
  position: absolute;
  padding: 16px;
  background-color: #fff;
  box-shadow: 0 4px 6px #333;
  border-radius: 2px;
  height: 72px;
  width: 200px;
}
.annotate-box h3 {
  font-size: 14px;
  font-weight: 500;
  font-family: 'Helvetica Neue, Segoe UI, san-serif';
  color: #484848;
}
.annotation-data-view.ql-editor::-webkit-scrollbar {
  width: 3px;
}
.annotation-data-view.ql-editor p {
  display: block !important;
}
.annotate-target {
  color: #fff;
  background-color: #03a9f4;
  height: 21px;
  width: 21px;
  border-radius: 100px;
  position: absolute;
  border: 2px #5cb7f3 solid;
  font-family: 'Helvetica Neue, Segoe UI, san-serif';
  font-size: 12px;
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
}
.drag-annotation {
  align-items: unset !important;
  justify-content: unset !important;
  padding: 16px !important;
  padding: 20px 10px !important;
  display: flex;
  align-items: center;
  justify-content: center;
  border: solid 1px #ddd;
  background: #f0f0f0;
  position: absolute;
  z-index: 111;
  box-shadow: #cccccc 0px 0px 2px 0px;
  border: 2px;
  border-radius: 2px;
}
.drag-annotation .mention {
  height: unset;
  width: unset;
  border-radius: unset;
  background-color: unset;
  padding: unset;
  margin-right: unset;
}
.drop-down-container {
  display: flex;
  align-items: center;
  flex: 0 0 100%;
  margin-bottom: 16px;
  justify-content: flex-end;
}
.drop-down-wrapper {
  position: relative;
  width: 150px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
}
.drag-annotation .menu-item,
.table-popup .menu-item {
  display: none;
  position: absolute;
  top: 5px;
  right: 0px;
