}
.inline-toolbar:after,
.inline-toolbar:before {
  top: 100%;
  left: 50%;
  border: solid transparent;
  content: " ";
  height: 0;
  width: 0;
  position: absolute;
  pointer-events: none;
}
.inline-toolbar:after {
  border-color: rgba(255, 255, 255, 0);
